out.pastel = [...document.querySelectorAll('.primary-pastel-01')].map(e=>({...desc(e), html: e.outerHTML.slice(0,300), cs: getComputedStyle(e).color+'/'+getComputedStyle(e).backgroundColor}));
out.content = [...document.querySelectorAll('.content')].map(e=>({...desc(e), html: e.outerHTML.slice(0,300)}));
out.filters = [...document.querySelectorAll('main [class*="cursor"], main .br-tag, main [class*="filter"]')].slice(0,20).map(e=>({...desc(e), html: e.outerHTML.slice(0,250)}));
out.tabs = [...document.querySelectorAll('nav[aria-label="Abas de Navegação Simples"] li')].map(li=>({li: desc(li), html: li.outerHTML.slice(0,300)}));
out.h = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6,[role=heading]')].map(desc);
out.landmarks = [...document.querySelectorAll('header,nav,main,footer,aside,[role=banner],[role=navigation],[role=main],[role=contentinfo]')].map(desc);
out.skip = [...document.querySelectorAll('a')].slice(0,5).map(a=>({...desc(a), href: a.getAttribute('href')}));
return out;
}"}

{"function":"() => {
const out = {};
const desc = el => el ? {tag: el.tagName, cls: (el.className||'').toString().slice(0,80), id: el.id, role: el.getAttribute('role'), tabindex: el.getAttribute('tabindex'), aria: [...el.attributes].filter(a=>a.name.startsWith('aria')||a.name==='title').map(a=>a.name+'='+a.value).join(';'), text: (el.innerText||'').trim().slice(0,60)} : null;
// header
const hdr = document.querySelector('[aria-label="Plataforma Nacional da Indústria do Pescado"]');
out.hdr = hdr ? {html: hdr.outerHTML.slice(0,600), tag: hdr.tagName, sr: !!hdr.shadowRoot} : null;
// avatar
const av = [...document.querySelectorAll('button')].find(b=>b.getAttribute('aria-label')==='Avatar com dropdown' || /Avatar/.test(b.textContent));
out.av = av ? {html: av.outerHTML.slice(0,700), parent: av.parentElement.outerHTML.slice(0,200)} : 'none';
const c = document.querySelector('.content'); if (c) {const cs=getComputedStyle(c); out.avatarLetter={fs:cs.fontSize, fw:cs.fontWeight, color:cs.color, bg:cs.backgroundColor, ariaHidden: c.closest('[aria-hidden]')?.outerHTML.slice(0,100)};}
// search input
const si = document.querySelector('input[placeholder="Pesquise aqui ..."]');
out.search = si ? {html: si.outerHTML, labels: si.labels ? [...si.labels].map(l=>l.outerHTML):null, parent: si.closest('.br-input')?.outerHTML.slice(0,500)} : 'not in light DOM';
// date
out.dateArea = document.evaluate("//*[contains(text(),'Data da vistoria')]", document, null, 9, null).singleNodeValue?.parentElement.outerHTML.slice(0,1500);
// buttons in actions col row1
const row1 = document.querySelector('tbody tr');
out.row1Actions = row1.querySelector('td:nth-child(9)').outerHTML.slice(0,3000);
return out;
}"}

